/**
 * Update kinematic bodies - position/quaternion synced from SAB (written by anime.js)
 * Handles parent-child matrix relationships for hierarchical kinematic bodies
 *
 * IMPORTANT: This function reads from SAB BEFORE storing previous state,
 * so that applyKinematicMove can calculate correct velocity transfer.
 *
 * NOTE: Spatial grid updates for kinematics are disabled because the cost of
 * updating the grid every frame (remove + insert per body) exceeds the benefit.
 * Frustum culling alone is sufficient for kinematic bodies.
 */
export function updateKinematic(bodies: any, parentMatrix: any, forceUpdate: any): void;
